import{Lt as e,Vt as t,_t as n,bt as r,mt as i,vt as a,yt as o}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";import{n as s,t as c}from"./chunks/PluginFeedback.BpCHXCV1.js";var l=JSON.parse(`{"title":"百度翻译接口申请和配置","description":"","frontmatter":{"plugin":"windingwind/zotero-pdf-translate"},"headers":[],"relativePath":"user-guide/plugins/translate/baidu.md","filePath":"wiki/user-guide/plugins/translate/baidu.md"}`),u=Object.assign({name:`user-guide/plugins/translate/baidu.md`},{setup(l){return(l,u)=>{let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),n(`div`,null,[u[0]||=i(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidepluginstranslatebaidu.md for this page in Markdown format`,-1),u[1]||=i(`h1`,{id:`百度翻译接口申请和配置`,tabindex:`-1`},[o(`百度翻译接口申请和配置 `),i(`a`,{class:`header-anchor`,href:`#百度翻译接口申请和配置`,"aria-label":`Permalink to “百度翻译接口申请和配置”`},`​`)],-1),r(s),u[2]||=a(`<p>百度翻译和垂直领域翻译免费额度：</p><ul><li><a href="https://fanyi-api.baidu.com/product/111" target="_blank" rel="noreferrer">通用翻译</a>：完成个人认证可升级使用高级版服务，提供基础文本翻译服务，支持自定义术语翻译功能。<strong>每月 100 万字符免费</strong>，QPS 为 10，单次最长请求 6000 字符，支持 28 个常见语种。</li><li><a href="https://fanyi-api.baidu.com/product/12" target="_blank" rel="noreferrer">垂直领域翻译</a>: 开通并认证后，即享<strong>每月 50 万免费字符</strong>。目前已开通学术论文、生物医药、信息技术、金融财经、机械制造、网络文学（仅支持中英）、新闻资讯、人文社科（仅支持中英）、航空航天、法律法规、合同共 11 个垂直领域。</li></ul><p>以上接口，超出部分按 49 元/百万字符计费，垂直领域接口申请成功后的提示：高级版是每月 100W 字符。</p><h2 id="_1-账号注册" tabindex="-1">1. 账号注册 <a class="header-anchor" href="#_1-账号注册" aria-label="Permalink to “1. 账号注册”">​</a></h2><p>直接访问 <a href="https://fanyi-api.baidu.com/product/11" target="_blank" rel="noreferrer">https://fanyi-api.baidu.com/product/11</a>，如果未登录，点击右上角登录。没百度账号的同学，就直接新注册一个。</p><p><img src="/assets/baidu-3.Aga2hVkz.png" alt="登录按钮" width="1080" height="429"></p><p>网页上直接列出了通用文本翻译和领域翻译，这两个就是常说的百度翻译和百度垂直领域翻译。这两个的区别是：</p><ul><li>免费额度不同，垂直领域相比通用文本翻译免费额度少，每月只有 50W</li><li>精细度不同。为了提升特定领域机器翻译的准确度，百度翻译针对多个垂直领域模型进行了优化，特定领域术语翻译相较于通用文本翻译 API 结果更为准确，句式更加符合该行业特点。</li></ul><p>目前已开通科技电子、水利机械、生物医药等 3 个垂直领域，不过只有生物医药支持中英互译，剩下两个只支持中文到英文。建议生物医药相关专业的同学，可以试试使用垂直领域翻译接口。</p><p>访问 <a href="https://fanyi-api.baidu.com/product/11" target="_blank" rel="noreferrer">https://fanyi-api.baidu.com/product/11</a>，直接点击下方立即使用：</p><p><img src="/assets/baidu-4.BRLtk9L6.png" alt="开通通用文本翻译 API" width="1080" height="702"></p><p>点击之后可能出现验证（手机或实名制认证），请按照说明进行验证，提升免费额度。</p><p><img src="/assets/baidu-5.CpqFQ3LN.png" alt="实名认证窗口" width="634" height="250"></p><p>然后需要注册成为百度翻译开发者，请选择个人开发者，并如实填下方表格中的信息。</p><p><img src="/assets/baidu-6.DLi7qmaP.png" alt="个人开发者注册表格" width="631" height="927"></p><p>选择下方高级版，每月 100W 免费额度。</p><p><img src="/assets/baidu-7.Bfvu1Glo.png" alt="选择高级版" width="715" height="763"></p><h2 id="_2-百度翻译-通用文本翻译-接口申请" tabindex="-1">2. 百度翻译（通用文本翻译）接口申请 <a class="header-anchor" href="#_2-百度翻译-通用文本翻译-接口申请" aria-label="Permalink to “2. 百度翻译（通用文本翻译）接口申请”">​</a></h2><p>访问 <a href="https://fanyi-api.baidu.com/choose" target="_blank" rel="noreferrer">https://fanyi-api.baidu.com/choose</a> ，选择通用文本翻译，点下一步：</p><p><img src="/assets/baidu-8.BHOJ5yp3.png" alt="通用文本翻译 API 开通" width="1080" height="763"></p><p><img src="/assets/baidu-9.B5IQl8AF.png" alt="开通高级版" width="1019" height="843"></p><p><img src="/assets/baidu-10.swN4OHdo.png" alt="申请认证" width="1047" height="529"></p><p>应用名称是必填的，其他随意写。最后点击提交申请。</p><p><img src="/assets/baidu-11.B40FVvEu.png" alt="提交申请" width="1071" height="942"></p><p><img src="/assets/baidu-12.BaMldJ93.png" alt="开通成功后的个人页面" width="1080" height="592"></p><p>上图是开通成功后的页面。</p><h2 id="_3-百度垂直领域-领域翻译-接口申请" tabindex="-1">3. 百度垂直领域（领域翻译）接口申请 <a class="header-anchor" href="#_3-百度垂直领域-领域翻译-接口申请" aria-label="Permalink to “3. 百度垂直领域（领域翻译）接口申请”">​</a></h2><p>打开这个网页 <a href="https://fanyi-api.baidu.com/choose" target="_blank" rel="noreferrer">https://fanyi-api.baidu.com/choose</a>，选择领域翻译，点下一步：</p><p><img src="/assets/baidu-13.4qCpSWgd.png" alt="垂直领域翻译接口开通" width="1080" height="771"></p><p><img src="/assets/baidu-14.D1TJmnIe.png" alt="申请表格" width="639" height="912"></p><p><img src="/assets/baidu-15.J9g4ukVc.png" alt="垂直领域翻译接口开通成功后的个人页面" width="1080" height="564"></p><p><a href="https://fanyi-api.baidu.com/api/trans/product/desktop?req=field" target="_blank" rel="noreferrer">https://fanyi-api.baidu.com/api/trans/product/desktop?req=field</a> 垂直领域的后台界面，上面有对应的使用明细。</p><h2 id="_4-接口密钥查询" tabindex="-1">4. 接口密钥查询 <a class="header-anchor" href="#_4-接口密钥查询" aria-label="Permalink to “4. 接口密钥查询”">​</a></h2><p>打开 <a href="https://fanyi-api.baidu.com/api/trans/product/desktop" target="_blank" rel="noreferrer">https://fanyi-api.baidu.com/api/trans/product/desktop</a>，可以在最下面看到配置使用的 APP ID 和密钥。</p><p><img src="/assets/baidu-16.RkzxER8w.png" alt="接口密钥查看页面" width="879" height="941"></p><p>垂直领域翻译还需要一个领域参数，具体领域信息如下：</p><table tabindex="0"><thead><tr><th>支持传入值</th><th>描述</th><th>支持语言方向</th></tr></thead><tbody><tr><td>it</td><td>信息技术领域</td><td>中文（简）-&gt; 英语、英语 -&gt; 中文（简）</td></tr><tr><td>finance</td><td>金融财经领域</td><td>中文（简）-&gt; 英语、英语 -&gt; 中文（简）</td></tr><tr><td>machinery</td><td>机械制造领域</td><td>中文（简）-&gt; 英语、英语 -&gt; 中文（简）</td></tr><tr><td>senimed</td><td>生物医药领域</td><td>中文（简）-&gt; 英语、英语 -&gt; 中文（简）</td></tr><tr><td>novel</td><td>网络文学领域</td><td>中文（简）-&gt; 英语</td></tr><tr><td>academic</td><td>学术论文领域</td><td>中文（简）-&gt; 英语、英语 -&gt; 中文（简）</td></tr><tr><td>aerospace</td><td>航空航天领域</td><td>中文（简）-&gt; 英语、英语 -&gt; 中文（简）</td></tr><tr><td>wiki</td><td>人文社科领域</td><td>中文（简）-&gt; 英语</td></tr><tr><td>news</td><td>新闻资讯领域</td><td>中文（简）-&gt; 英语、英语 -&gt; 中文（简）</td></tr><tr><td>law</td><td>法律法规领域</td><td>中文（简）-&gt; 英语、英语 -&gt; 中文（简）</td></tr><tr><td>contract</td><td>合同领域</td><td>中文（简）-&gt; 英语、英语 -&gt; 中文（简）</td></tr></tbody></table><p>以上信息参考 <a href="https://fanyi-api.baidu.com/product/123" target="_blank" rel="noreferrer">百度开发文档</a>。</p><p>这里假设我申请到的 APP ID 为 <code>12345</code>，密钥为 <code>abcde</code>，选择生物医药领域为 <code>medicine</code>。介绍如何在 Zotero 翻译插件中设置。</p><h3 id="_4-1-百度翻译设置" tabindex="-1">4.1 百度翻译设置 <a class="header-anchor" href="#_4-1-百度翻译设置" aria-label="Permalink to “4.1 百度翻译设置”">​</a></h3><p><img src="/assets/baidu-18.DtF3jSA9.png" alt="翻译插件设置窗口" width="1080" height="848"></p><p>提示窗口点 OK：</p><p><img src="/assets/baidu-19.C8NPQ1pY.png" alt="弹窗提示" width="1016" height="350"></p><p><img src="/assets/baidu-20.DkDTuAv3.png" alt="密钥填写处" width="1080" height="848"></p><p>这里填入 <code>12345#abcde</code>。</p><h3 id="_4-2-百度垂直领域-领域翻译-设置" tabindex="-1">4.2 百度垂直领域（领域翻译）设置 <a class="header-anchor" href="#_4-2-百度垂直领域-领域翻译-设置" aria-label="Permalink to “4.2 百度垂直领域（领域翻译）设置”">​</a></h3><p><img src="/assets/baidu-21.C3OyJv3u.png" alt="垂直领域密钥设置窗口" width="1080" height="848"></p><p><img src="/assets/baidu-22.Bo8VW2u4.png" alt="密钥填写处" width="1080" height="848"></p><p>密钥处填入 <code>12345#abcde#medicine</code>。</p><h2 id="_5-接口测试" tabindex="-1">5. 接口测试 <a class="header-anchor" href="#_5-接口测试" aria-label="Permalink to “5. 接口测试”">​</a></h2><p>这里以百度垂直领域引擎为例进行测试，在 Zotero 中打开一篇英文 PDF，划词翻译，如下图正常翻译，就说明配置正常。</p><p><img src="/assets/baidu-23.0lWseFfT.png" alt="配置翻译服务" width="1080" height="613"></p>`,52),r(c),r(d),r(f)])}}});export{l as __pageData,u as default};